INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',1,'Coloca una barra en un soporte de sentadillas a la altura del pecho.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',2,'Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',3,'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',4,'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',5,'Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',6,'Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',7,'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0026',8,'Repite el número de repeticiones deseado.') ON CONFLICT DO NOTHING;
