INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-1316',2,'Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-1316',3,'Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-1316',4,'Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.') ON CONFLICT DO NOTHING;
