INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-2407',1,'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-2407',2,'Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-2407',3,'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-2407',4,'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-2407',5,'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-2407',6,'Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.') ON CONFLICT DO NOTHING;
