INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0028',1,'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0028',2,'Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0028',3,'Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0028',4,'Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0028',5,'Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0028',6,'Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0028',7,'Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.') ON CONFLICT DO NOTHING;
