INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0029',1,'Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0029',2,'Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0029',3,'Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0029',4,'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0029',5,'Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.') ON CONFLICT DO NOTHING;
INSERT INTO exercise_instructions (exercise_id,step_number,instruction_es) VALUES ('og-0029',6,'Repite el número de repeticiones deseado.') ON CONFLICT DO NOTHING;
